package models

import (
	"fmt"
	"time"

	"github.com/nyaruka/gocommon/aws/dynamo"
	"github.com/nyaruka/gocommon/httpx"
	"github.com/nyaruka/gocommon/svclogs"
	"github.com/nyaruka/goflow/core"
	"github.com/nyaruka/goflow/core/events"
)

const (
	AirtimeLogTypeCreate  svclogs.Type = "create"
	AirtimeLogTypeConfirm svclogs.Type = "confirm"

	airtimeLogDynamoTTL = time.Hour * 24 * 7 // 1 week
)

// AirtimeLog stores the HTTP logs and errors generated by an interaction with an airtime provider for a transfer.
type AirtimeLog struct {
	*svclogs.Log

	orgID        OrgID
	transferUUID events.EventUUID
}

// NewAirtimeLog creates a new airtime log for the given transfer from HTTP logs which have already been redacted by
// the airtime service that made the calls.
func NewAirtimeLog(t svclogs.Type, orgID OrgID, transferUUID events.EventUUID, httpLogs []*core.HTTPLog, err error) *AirtimeLog {
	l := &AirtimeLog{Log: svclogs.New(t, nil, nil), orgID: orgID, transferUUID: transferUUID}

	// the calls have already been made so timing comes from the HTTP logs rather than from when this log is created
	if len(httpLogs) > 0 {
		l.CreatedOn = httpLogs[0].CreatedOn
	}
	for _, h := range httpLogs {
		l.HttpLogs = append(l.HttpLogs, &httpx.Log{LogWithoutTime: h.LogWithoutTime, CreatedOn: h.CreatedOn})
		l.Elapsed += time.Duration(h.ElapsedMS) * time.Millisecond
	}
	if err != nil {
		l.Error(&svclogs.Error{Message: err.Error()})
	}

	return l
}

// AirtimeLogDynamoKey returns the DynamoDB key for the airtime log with the given UUID
func AirtimeLogDynamoKey(transferUUID events.EventUUID, logUUID svclogs.UUID) dynamo.Key {
	return dynamo.Key{PK: fmt.Sprintf("att#%s", transferUUID), SK: fmt.Sprintf("log#%s", logUUID)}
}

func (l *AirtimeLog) DynamoKey() dynamo.Key {
	return AirtimeLogDynamoKey(l.transferUUID, l.UUID)
}

func (l *AirtimeLog) MarshalDynamo() (*dynamo.Item, error) {
	type DataGZ struct {
		HttpLogs []*httpx.Log     `json:"http_logs"`
		Errors   []*svclogs.Error `json:"errors"`
	}

	dataGZ, err := dynamo.MarshalJSONGZ(&DataGZ{HttpLogs: l.HttpLogs, Errors: l.Errors})
	if err != nil {
		return nil, fmt.Errorf("error encoding airtime log as JSON+GZip: %w", err)
	}

	ttl := l.CreatedOn.Add(airtimeLogDynamoTTL)

	return &dynamo.Item{
		Key:   l.DynamoKey(),
		OrgID: int(l.orgID),
		TTL:   &ttl,
		Data: map[string]any{
			"type":       l.Type,
			"elapsed_ms": int(l.Elapsed / time.Millisecond),
			"created_on": l.CreatedOn,
			"is_error":   l.IsError(),
		},
		DataGZ: dataGZ,
	}, nil
}
